    def transcribe_and_translate(
        self,
        video_path: str,
        source_lang: str = "auto",
        youtube_url: Optional[str] = None,
        asr_segments: Optional[List[Dict[str, Any]]] = None,
    ) -> List[Dict[str, Any]]:
        """视频 → 带时间戳的双语字幕 dict 列表

        Args:
            video_path: 本地视频路径
            source_lang: 原语言
            youtube_url: YouTube URL（可选）
            asr_segments: 本地 ASR 参考结果（List[dict]，含 start_time/end_time/text）
                          有这个时 Gemini 会对照 ASR 做翻译+分句，不容易漏字幕

        Returns:
            List[dict] — 每项含 start_time, end_time, source_text, target_text
        """
        if not self.is_available:
            raise RuntimeError("Gemini 未启用或 api_key 未配置")

        client = self._get_client()

        if asr_segments:
            asr_text = self._serialize_asr_segments_for_prompt(asr_segments)
            prompt = self.PROMPT_WITH_ASR_REF.format(
                source_lang=source_lang, asr_reference=asr_text
            )
            logger.info(
                f"[Gemini] 使用 ASR 参考模式: {len(asr_segments)} 段"
            )
        else:
            prompt = self.PROMPT_TEMPLATE.format(source_lang=source_lang)
            logger.info("[Gemini] 独立 ASR 模式（无本地参考）")

        # 文件只上传一次，后续所有模型共用（f.name 是文件 URI，不绑定模型）
        gemini_input = self._prepare_input(client, video_path, youtube_url)

        model_chain: List[str] = list(self._model_chain)

        logger.info(
            f"[Gemini] 开始处理视频: {os.path.basename(video_path)}, "
            f"source_lang={source_lang}, model_chain={model_chain}"
        )
        t0 = time.time()
        api_call_count = 0   # ← 本次总共尝试了多少次 generate_content
        api_total_time = 0.0

        import random
        response = None
        last_exc: Optional[Exception] = None
        exhausted_models: List[str] = []

        for idx, model in enumerate(model_chain):
            # 跳过已标记"今日耗尽"的模型
            if _is_model_exhausted(model):
                logger.info(f"[Gemini] [{model}] 今日已耗尽，跳过")
                exhausted_models.append(model)
                continue

            for attempt in range(1, self.RETRIES_PER_MODEL + 1):
                try:
                    api_call_count += 1
                    t_call = time.time()
                    logger.info(
                        f"[Gemini] → API 调用 #{api_call_count}: model={model}, "
                        f"attempt={attempt}/{self.RETRIES_PER_MODEL}"
                    )
                    self._log_prompt(f"ASR[{model}]", prompt)
                    with GEMINI_RATE_LIMITER:
                        response = client.models.generate_content(
                            model=model,
                            contents=[gemini_input, prompt],
                        )
                    call_elapsed = time.time() - t_call
                    api_total_time += call_elapsed
                    logger.info(
                        f"[Gemini] ← API 调用 #{api_call_count} 成功: "
                        f"{model}, 耗时 {call_elapsed:.1f}s"
                    )
                    last_exc = None
                    break
                except Exception as e:
                    last_exc = e
                    call_elapsed = time.time() - t_call
                    api_total_time += call_elapsed
                    msg = str(e)
                    logger.warning(
                        f"[Gemini] ← API 调用 #{api_call_count} 失败: "
                        f"{model}, attempt={attempt}, 耗时 {call_elapsed:.1f}s, "
                        f"错误={msg[:120]}"
                    )
                    if _is_429(e):
                        is_quota = _is_quota_exhausted(e)
                        delay = _extract_retry_delay(e) or 10.0
                        if is_quota:
                            # ★ 真的配额耗尽（quota/daily limit）→ 标记模型今日废掉
                            exh_model = _extract_exhausted_model(e)
                            if exh_model:
                                _mark_model_exhausted(exh_model)
                            else:
                                _mark_model_exhausted(model)
                            logger.warning(
                                f"[Gemini] [{model}] ❗ 今日配额耗尽 "
                                f"(quota_exhausted=True) → 标记今日耗尽，降级下一模型"
                            )
                        else:
                            # ★ 普通 Rate Limit 429（RPM 超限等暂时问题）
                            # 只 sleep 当前线程，不标记模型、不塞全局 limiter
                            logger.warning(
                                f"[Gemini] [{model}] ⚠ RPM 限流 "
                                f"(quota_exhausted=False) → 等待 {delay:.1f}s 后降级"
                            )
                            time.sleep(delay)
                        break  # 直接跳出 attempt 循环，降级下一模型
                    if is_retryable_error(e) and attempt < self.RETRIES_PER_MODEL:
                        backoff = _backoff_seconds(attempt)
                        if self._is_connection_error(e):
                            # ★ 连接类错误（VPN 重连 / TCP RST）→ 必须重建连接池
                            logger.warning(
                                f"[Gemini] [{model}] 🔌 连接类错误 → "
                                f"重建 httpx 连接池后 retry {attempt + 1}/{self.RETRIES_PER_MODEL}"
                            )
                            client = self._reset_client()
                        else:
                            logger.warning(
                                f"[Gemini] [{model}] API 失败 "
                                f"(retry {attempt}/{self.RETRIES_PER_MODEL}): "
                                f"{msg[:120]} — {backoff:.1f}s 后重试"
                            )
                        time.sleep(backoff)
                        continue
                    # 不可重试 或 已用尽重试 → 切下一个模型
                    break

            if response is not None:
                break  # 成功，跳出模型循环

            logger.warning(
                f"[Gemini] [{model}] 全部重试失败 → 降级到下一个模型"
            )

        if response is None:
            elapsed = time.time() - t0
            logger.error(
                f"[Gemini] 全部 {len(model_chain)} 个模型尝试均失败 "
                f"({elapsed:.1f}s): API调用{api_call_count}次, "
                f"API总耗时{api_total_time:.1f}s, 最后错误: {last_exc}"
            )
            self._cleanup_file(client)
            raise RuntimeError(f"Gemini API error (all models failed): {last_exc}") from last_exc

        elapsed = time.time() - t0
        logger.info(
            f"[Gemini] ✅ API 返回成功: 总耗时 {elapsed:.1f}s, "
            f"API 调用 {api_call_count} 次, API 累计耗时 {api_total_time:.1f}s"
        )

        self._cleanup_file(client)

        items = self._parse_response(response)
        logger.info(f"[Gemini] 解析到 {len(items)} 条字幕项")

        if not items:
            raise RuntimeError("Gemini 返回空结果")

        return items


    def proofread_subtitles(
        self,
        video_path: str,
        existing_items: List[Dict[str, Any]],
        source_lang: str = "auto",
        asr_segments: Optional[List[Dict[str, Any]]] = None,
    ) -> List[Dict[str, Any]]:
        """把烧录好字幕的视频 + 现有字幕列表送给 Gemini 做二次校对

        Args:
            video_path: 已烧录字幕的视频文件路径
            existing_items: 当前字幕 dict 列表（画面里烧录的字幕）
            source_lang: 原语言
            asr_segments: 本地 ASR 参考结果（可选，对照补漏更准）

        Returns:
            修正后的完整字幕 dict 列表
        """
        if not self.is_available:
            raise RuntimeError("Gemini 未启用或 api_key 未配置")

        client = self._get_client()
        existing_srt_text = self._serialize_items_for_prompt(existing_items)

        if asr_segments:
            asr_text = self._serialize_asr_segments_for_prompt(asr_segments)
            prompt = self.PROOFREAD_WITH_ASR_REF.format(
                existing_srt=existing_srt_text, asr_reference=asr_text
            )
            logger.info(
                f"[Gemini 校对] 使用 ASR 参考模式: "
                f"现有 {len(existing_items)} 条字幕 + ASR {len(asr_segments)} 段"
            )
        else:
            prompt = self.PROOFREAD_PROMPT.format(existing_srt=existing_srt_text)
            logger.info(
                f"[Gemini 校对] 独立校对模式（无 ASR 参考）: "
                f"现有 {len(existing_items)} 条字幕"
            )

        gemini_input = self._prepare_input(client, video_path, None)

        model_chain: List[str] = list(self._model_chain)

        logger.info(
            f"[Gemini 校对] 开始: {os.path.basename(video_path)}, "
            f"现有 {len(existing_items)} 条字幕, model_chain={model_chain}"
        )
        t0 = time.time()

        import random
        response = None
        last_exc: Optional[Exception] = None

        for idx, model in enumerate(model_chain):
            if _is_model_exhausted(model):
                logger.info(f"[Gemini 校对] [{model}] 今日已耗尽，跳过")
                continue

            for attempt in range(1, self.RETRIES_PER_MODEL + 1):
                try:
                    self._log_prompt(f"校对[{model}]", prompt)
                    with GEMINI_RATE_LIMITER:
                        response = client.models.generate_content(
                            model=model,
                            contents=[gemini_input, prompt],
                        )
                    last_exc = None
                    break
                except Exception as e:
                    last_exc = e
                    msg = str(e)
                    if _is_429(e):
                        is_quota = _is_quota_exhausted(e)
                        delay = _extract_retry_delay(e) or 10.0
                        if is_quota:
                            exh_model = _extract_exhausted_model(e)
                            if exh_model:
                                _mark_model_exhausted(exh_model)
                            else:
                                _mark_model_exhausted(model)
                            logger.warning(
                                f"[Gemini 校对] [{model}] ❗ 今日配额耗尽 → 降级"
                            )
                        else:
                            logger.warning(
                                f"[Gemini 校对] [{model}] ⚠ RPM 限流 → 等待 {delay:.1f}s 后降级"
                            )
                            time.sleep(delay)
                        break   # 不再内部重试当前模型
                    if is_retryable_error(e) and attempt < self.RETRIES_PER_MODEL:
                        backoff = _backoff_seconds(attempt)
                        if self._is_connection_error(e):
                            logger.warning(
                                f"[Gemini 校对] [{model}] 🔌 连接类错误 → "
                                f"重建 httpx 连接池后 retry {attempt + 1}/{self.RETRIES_PER_MODEL}"
                            )
                            client = self._reset_client()
                        else:
                            logger.warning(
                                f"[Gemini 校对] [{model}] API 失败 "
                                f"(retry {attempt}/{self.RETRIES_PER_MODEL}): {msg[:120]} "
                                f"— {backoff:.1f}s 后重试"
                            )
                        time.sleep(backoff)
                        continue
                    break

            if response is not None:
                break
            logger.warning(
                f"[Gemini 校对] [{model}] 全部重试失败 → 降级"
            )

        if response is None:
            elapsed = time.time() - t0
            logger.error(
                f"[Gemini 校对] 全部 {len(model_chain)} 个模型均失败 ({elapsed:.1f}s): {last_exc}"
            )
            self._cleanup_file(client)
            raise RuntimeError(f"Gemini proofread error: {last_exc}") from last_exc

        elapsed = time.time() - t0
        logger.info(f"[Gemini 校对] API 返回成功 ({elapsed:.1f}s)")

        self._cleanup_file(client)

        items = self._parse_response(response)
        logger.info(
            f"[Gemini 校对] 解析到 {len(items)} 条（原 {len(existing_items)} 条）"
        )
        return items


    def transcribe_to_srt_file(
        self,
        video_path: str,
        source_lang: str = "auto",
        proofread: bool = False,
    ) -> Optional[str]:
        """完整流水线：ASR → 翻译 → (可选校对) → SRT 文件落盘

        Args:
            video_path: 本地视频路径
            source_lang: 原语言代码（"auto" 让 Gemini 自动检测）
            proofread: 是否启用校对（对已烧录字幕的视频推荐开启）

        Returns:
            成功 → 写入的 SRT 文件绝对路径
            失败 → None（异常由内部处理并记录日志，调用方只需判空）
        """
        import traceback
        from utils.srt_parser import write_srt_file

        t_total = time.time()
        logger.info(f"[Gemini ASR] ⏱ 开始流水线: {os.path.basename(video_path)}")

        # ---- Step 1: 本地 faster-whisper ASR（失败不致命，降级纯 Gemini） ----
        t1 = time.time()
        local_asr: List[Dict[str, Any]] = []
        try:
            from faster_whisper import WhisperModel
            models_dir = os.path.normpath(os.path.join(
                os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "models"))
            whisper_model = WhisperModel(
                "small", device="auto", compute_type="auto", download_root=models_dir)
            whisper_lang = source_lang if source_lang and source_lang != "auto" else None
            seg_gen, info = whisper_model.transcribe(
                video_path, beam_size=5, language=whisper_lang,
                vad_filter=True, vad_parameters={"min_silence_duration_ms": 500},
            )
            for seg in seg_gen:
                local_asr.append({
                    "start_time": float(seg.start or 0),
                    "end_time": float(seg.end or 0),
                    "text": (seg.text or "").strip(),
                })
            logger.info(
                f"[Gemini ASR] [1/4] 本地 ASR: {len(local_asr)} 段, "
                f"lang={getattr(info, 'language', '?')}, "
                f"耗时 {time.time()-t1:.1f}s"
            )
        except Exception as e:
            logger.warning(
                f"[Gemini ASR] [1/4] 本地 ASR 失败，降级纯 Gemini: {e}, "
                f"耗时 {time.time()-t1:.1f}s"
            )

        # ---- Step 2: Gemini 识别 + 翻译 ----
        t2 = time.time()
        try:
            segments = self.transcribe_and_translate(
                video_path, source_lang=source_lang,
                asr_segments=local_asr if local_asr else None,
            )
            logger.info(
                f"[Gemini ASR] [2/4] Gemini 识别+翻译完成, "
                f"耗时 {time.time()-t2:.1f}s"
            )
        except Exception as e:
            logger.error(
                f"[Gemini ASR] [2/4] Gemini 识别异常: {e}, "
                f"耗时 {time.time()-t2:.1f}s\n{traceback.format_exc()}"
            )
            return None

        if not segments:
            logger.error("[Gemini ASR] [2/4] Gemini 返回空结果")
            return None

        # ---- Step 3: 校对（可选） ----
        t3 = time.time()
        if proofread:
            try:
                segments = self.proofread_subtitles(
                    video_path, segments, source_lang=source_lang,
                    asr_segments=local_asr if local_asr else None,
                )
                logger.info(
                    f"[Gemini ASR] [3/4] 校对完成, 耗时 {time.time()-t3:.1f}s"
                )
            except Exception as e:
                logger.warning(
                    f"[Gemini ASR] [3/4] 校对失败，保留原结果: {e}, "
                    f"耗时 {time.time()-t3:.1f}s"
                )

        # ---- Step 4: 写 SRT ----
        t4 = time.time()
        out_dir = os.path.dirname(video_path)
        base = os.path.splitext(os.path.basename(video_path))[0]
        srt_path = os.path.join(out_dir, f"{base}_zh-CN.srt")

        try:
            write_srt_file(segments, srt_path, bilingual=True)
            total = time.time() - t_total
            logger.info(
                f"[Gemini ASR] [4/4] ✅ SRT 写入完成: {os.path.basename(srt_path)} "
                f"({len(segments)} 条), 本次总耗时 {total:.1f}s"
            )
            return srt_path
        except Exception as e:
            logger.error(f"[Gemini ASR] [4/4] SRT 写入失败: {e}")
            return None


    @classmethod
    def _filter_hallucinated_overlays(cls, items: list) -> list:
        """对 Gemini 封面本地化返回的 JSON 条目做多模态幻觉黑名单过滤。

        典型幻觉：Gemini 把 YouTube 训练数据中的常见 UI 按钮（立即观看/精彩内容/...）
        幻觉成封面上的真实文字，生成 overlay=true 的条目去覆盖原图。这些条目必须丢弃。

        返回：过滤后的 items 列表（原地修改 overlay 字段，不删除）
        """
        filtered_count = 0
        for it in items:
            if not isinstance(it, dict):
                continue
            if not it.get("overlay"):
                continue  # overlay=false 的条目本来就不会画，跳过
            translation = (it.get("translation") or "").strip()
            if not translation:
                continue
            low = translation.lower()
            for kw in cls._HALLUCINATION_BLOCKLIST:
                if kw.lower() in low:
                    it["overlay"] = False
                    filtered_count += 1
                    logger.warning(
                        f"[Gemini 封面] 屏蔽幻觉条目 "
                        f"(命中 '{kw}'): text='{it.get('text','')}' → translation='{translation}'"
                    )
                    break
        if filtered_count:
            logger.warning(
                f"[Gemini 封面] 后处理共屏蔽 {filtered_count} 条幻觉 overlay"
            )
        return items


    @staticmethod
    def _serialize_asr_segments_for_prompt(
        asr_segments: List[Dict[str, Any]], max_lines: int = 800
    ) -> str:
        """把本地 ASR segments 序列化成紧凑文本，塞进 prompt 作为补漏参考

        asr_segments 的每条含 start_time / end_time / text（原文）
        """
        lines: List[str] = []
        for i, seg in enumerate(asr_segments[:max_lines], 1):
            st = seg.get("start_time", 0)
            et = seg.get("end_time", 0)
            txt = str(seg.get("text", seg.get("source_text", ""))).replace("\n", " ").strip()
            if txt:
                lines.append(f"{i}. [{st:.1f}s-{et:.1f}s] {txt}")
        if len(asr_segments) > max_lines:
            lines.append(
                f"... (共 {len(asr_segments)} 段，此处只列前 {max_lines} 段)"
            )
        return "\n".join(lines)


    def _prepare_input(self, client, video_path: str, youtube_url: Optional[str]):
        t_prepare = time.time()

        if self._use_youtube_url and youtube_url and youtube_url.startswith("http"):
            logger.info(f"[Gemini] _prepare_input: 使用 YouTube URL (耗时 {time.time()-t_prepare:.1f}s)")
            return youtube_url

        if not os.path.exists(video_path):
            raise FileNotFoundError(f"视频文件不存在: {video_path}")

        # ====== 纯音频模式：先从视频抽音轨 ======
        t_audio = time.time()
        upload_path = video_path
        upload_kind = "视频"
        if self._use_audio_only:
            audio_path = self._extract_audio(video_path)
            audio_elapsed = time.time() - t_audio
            if audio_path:
                upload_path = audio_path
                upload_kind = "音频"
                self._temp_audio = audio_path
                logger.info(
                    f"[Gemini] 音频提取完成: {audio_path} "
                    f"({os.path.getsize(audio_path)/1024/1024:.1f}MB, {audio_elapsed:.1f}s)"
                )
            else:
                logger.warning(
                    f"[Gemini] 音频提取失败，回退上传视频 (耗时 {audio_elapsed:.1f}s)"
                )

        file_size_mb = os.path.getsize(upload_path) / 1024 / 1024

        # google-genai SDK 内部对文件名做 ascii 编码，emoji/中文会炸
        # 复制成纯 ASCII 临时文件名再上传
        t_copy = time.time()
        safe_path = self._make_ascii_temp_copy(upload_path)
        logger.info(
            f"[Gemini] ASCII 临时文件复制: {file_size_mb:.1f}MB, "
            f"耗时 {time.time()-t_copy:.1f}s"
        )
        display_name = os.path.basename(upload_path)
        logger.info(f"[Gemini] 上传本地{upload_kind}: {display_name} ({file_size_mb:.1f}MB)")

        # ====== 阶段 1: 上传文件（失败才重传）======
        t_upload = time.time()
        last_exc: Optional[Exception] = None
        f = None
        upload_attempts = 0
        for attempt in range(1, self.UPLOAD_RETRIES + 1):
            upload_attempts += 1
            try:
                with GEMINI_RATE_LIMITER:
                    f = client.files.upload(file=safe_path)
                self._file_ref = f
                self._temp_upload_copy = safe_path
                logger.info(
                    f"[Gemini] 文件上传成功: {f.name} (attempt {attempt}, "
                    f"耗时 {time.time()-t_upload:.1f}s)"
                )
                break
            except Exception as e:
                last_exc = e
                if _is_429(e):
                    delay = _extract_retry_delay(e) or 10.0
                    logger.warning(
                        f"[Gemini] 文件上传 429 → 等待 {delay:.1f}s, "
                        f"retry {attempt}/{self.UPLOAD_RETRIES}"
                    )
                    time.sleep(delay)
                    continue
                if is_retryable_error(e) and attempt < self.UPLOAD_RETRIES:
                    wait = _backoff_seconds(attempt)
                    if self._is_connection_error(e):
                        logger.warning(
                            f"[Gemini] 文件上传 🔌 连接类错误 → "
                            f"重建 httpx 连接池后 retry {attempt + 1}/{self.UPLOAD_RETRIES}"
                        )
                        client = self._reset_client()
                    else:
                        logger.warning(
                            f"[Gemini] 文件上传失败 (retry {attempt}/{self.UPLOAD_RETRIES}): "
                            f"{str(e)[:120]} — {wait:.1f}s 后重试"
                        )
                    time.sleep(wait)
                    continue
                self._cleanup_temp_copy()
                raise RuntimeError(f"文件上传失败: {e}") from e

        if f is None:
            self._cleanup_temp_copy()
            raise RuntimeError(
                f"文件上传失败 (all {self.UPLOAD_RETRIES} attempts): {last_exc}"
            )

        # ====== 阶段 2: 等待 ACTIVE（不重传文件，只轮询状态）======
        # Google 服务端在 upload 后需要解析视频：短视频 ~5-15s，长视频可能要几分钟
        # 未就绪时调 generate_content 会被某些模型错误返回 403 PERMISSION_DENIED
        # 但等也有上限——给长视频 6 分钟，短视频 3 分钟
        video_duration_sec = 0.0
        try:
            import subprocess, json as _json
            r = subprocess.run(
                [
                    "ffprobe", "-v", "quiet",
                    "-print_format", "json",
                    "-show_entries", "format=duration",
                    video_path,
                ],
                capture_output=True, text=True, timeout=10,
            )
            if r.returncode == 0:
                video_duration_sec = float(
                    _json.loads(r.stdout).get("format", {}).get("duration", 0)
                )
        except Exception:
            video_duration_sec = 0.0

        wait_timeout = 360.0 if video_duration_sec > 300 else 180.0
        poll_interval = 3.0
        wait_deadline = time.time() + wait_timeout

        while time.time() < wait_deadline:
            try:
                f = client.files.get(name=f.name)
            except Exception as e:
                logger.debug(f"[Gemini] files.get({f.name}) 异常，继续等待: {e}")
                time.sleep(poll_interval)
                continue
            # state 是 FileState 枚举类型: str() → "FileState.ACTIVE", .value → "ACTIVE"
            _state_obj = getattr(f, "state", None)
            if _state_obj is None:
                state_upper = ""
            else:
                state_upper = (
                    getattr(_state_obj, "value", None)
                    or str(_state_obj).split(".")[-1]
                ).upper()

            if state_upper == "ACTIVE":
                self._file_ref = f
                if video_duration_sec > 0:
                    remaining = wait_deadline - time.time()
                    logger.info(
                        f"[Gemini] 文件已 ACTIVE ({video_duration_sec:.0f}s 视频), "
                        f"等待用时 {wait_timeout - remaining:.0f}s"
                    )
                else:
                    logger.info(f"[Gemini] 文件已 ACTIVE")
                return f
            if state_upper in ("FAILED", "STATE_UNSPECIFIED"):
                raise RuntimeError(
                    f"Gemini 文件解析失败: name={f.name}, state={state_upper}"
                )
            time.sleep(poll_interval)

        # 等超了——兜底：直接返回让 generate_content 去试
        # 虽然 PROCESSING 状态可能触发 403 bug，但也有可能部分模型能调通
        logger.warning(
            f"[Gemini] 文件等待 ACTIVE 超时 ({wait_timeout:.0f}s): {f.name} "
            f"(state={getattr(f, 'state', '?')}) — 兜底继续，让 generate_content 尝试"
        )
        self._file_ref = f
        return f


    @staticmethod
    def _extract_audio(video_path: str) -> Optional[str]:
        """从视频中抽音频为 mp3（96kbps mono），返回临时 mp3 路径

        失败返回 None（调用方会回退上传视频）。
        """
        import subprocess, tempfile, uuid, shutil

        tmp_dir = tempfile.gettempdir()
        safe_name = f"gemini_audio_{uuid.uuid4().hex}.mp3"
        audio_path = os.path.join(tmp_dir, safe_name)

        ffmpeg = "ffmpeg"
        for candidate in [
            "ffmpeg",
            "bin/ffmpeg/bin/ffmpeg.exe",
            os.path.join(os.path.dirname(video_path), "..", "..", "bin", "ffmpeg", "bin", "ffmpeg.exe"),
        ]:
            try:
                result = subprocess.run(
                    [candidate, "-version"],
                    capture_output=True, timeout=5,
                )
                if result.returncode == 0:
                    ffmpeg = candidate
                    break
            except Exception:
                continue

        try:
            result = subprocess.run(
                [
                    ffmpeg, "-y",
                    "-i", video_path,
                    "-vn",                # 不处理视频
                    "-acodec", "libmp3lame",
                    "-q:a", "4",          # ~128kbps，质量够 ASR 用
                    "-ac", "1",           # 单声道（省空间）
                    "-ar", "16000",       # 16kHz 采样率（ASR 标准）
                    audio_path,
                ],
                capture_output=True, timeout=300,
                encoding="utf-8", errors="replace",
            )
            if result.returncode == 0 and os.path.exists(audio_path) and os.path.getsize(audio_path) > 10240:
                return audio_path
            else:
                logger.debug(
                    f"[Gemini] ffmpeg 抽音频失败 rc={result.returncode}: "
                    f"{(result.stderr or '')[:200]}"
                )
                if os.path.exists(audio_path):
                    try: os.remove(audio_path)
                    except OSError: pass
                return None
        except Exception as e:
            logger.debug(f"[Gemini] ffmpeg 抽音频异常: {e}")
            if os.path.exists(audio_path):
                try: os.remove(audio_path)
                except OSError: pass
            return None


    @staticmethod
    def _make_ascii_temp_copy(src: str) -> str:
        """把 src 复制成一个纯 ASCII 的临时文件，返回新路径

        google-genai SDK 内部会用 ascii codec 编码文件名传给 multipart/form-data，
        遇到 emoji/中文文件名会抛 UnicodeEncodeError。
        """
        import shutil, tempfile, uuid
        ext = os.path.splitext(src)[1].lower()
        tmp_dir = tempfile.gettempdir()
        safe_name = f"gemini_upload_{uuid.uuid4().hex}{ext}"
        dst = os.path.join(tmp_dir, safe_name)
        shutil.copy2(src, dst)
        return dst


    def _cleanup_temp_copy(self) -> None:
        for attr in ("_temp_upload_copy", "_temp_audio"):
            p = getattr(self, attr, None)
            if p and os.path.exists(p):
                try:
                    os.remove(p)
                except OSError:
                    pass
            setattr(self, attr, None)


    def _cleanup_file(self, client) -> None:
        self._cleanup_temp_copy()
        if self._file_ref is None:
            return
        try:
            with GEMINI_RATE_LIMITER:
                client.files.delete(name=self._file_ref.name)
        except Exception:
            pass
        self._file_ref = None

